import java.nio.*;import java.nio.file.*;import java.util.*;import com.google.gson.*;import org.lwjgl.glfw.GLFW;import org.lwjgl.opengl.*;
/** Probe original binary compatibility without substituting shader sources. No simulation or FPS. */
public class R8BinaryProbe{public static void main(String[] a)throws Exception{Path root=Path.of(System.getProperty("cmi.r7.capture")),out=Path.of(System.getProperty("cmi.benchmark.output"));Files.createDirectories(out);var m=JsonParser.parseString(Files.readString(root.resolve("manifest.json"))).getAsJsonObject();GLFW.glfwInit();var rows=new ArrayList<Object>();for(int core=0;core<2;core++)for(int forward=0;forward<2;forward++)for(int debug=0;debug<2;debug++)for(int noerror=0;noerror<2;noerror++)for(int robust=0;robust<3;robust++){GLFW.glfwDefaultWindowHints();GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,6);GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_PROFILE,core==0?GLFW.GLFW_OPENGL_CORE_PROFILE:GLFW.GLFW_OPENGL_COMPAT_PROFILE);GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_FORWARD_COMPAT,forward);GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_DEBUG_CONTEXT,debug);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_NO_ERROR,noerror);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_ROBUSTNESS,robust==0?GLFW.GLFW_NO_ROBUSTNESS:robust==1?GLFW.GLFW_NO_RESET_NOTIFICATION:GLFW.GLFW_LOSE_CONTEXT_ON_RESET);long w=GLFW.glfwCreateWindow(32,32,"R8 binary compatibility",0,0);if(w==0){rows.add(Map.of("core",core,"forward",forward,"debug",debug,"noerror",noerror,"robust",robust,"created",false));continue;}GLFW.glfwMakeContextCurrent(w);GL.createCapabilities();if(!m.get("gpu").getAsString().equals(GL11.glGetString(GL11.GL_RENDERER))||!m.get("driver").getAsString().equals(GL11.glGetString(GL11.GL_VERSION)))throw new AssertionError("GPU/driver mismatch");int n=0;for(var entry:m.getAsJsonObject("programs").entrySet()){var d=entry.getValue().getAsJsonObject();byte[] raw=Files.readAllBytes(root.resolve(d.get("binary").getAsString()));String sha=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw));if(!sha.equals(m.getAsJsonObject("sha256").get(d.get("binary").getAsString()).getAsString()))throw new AssertionError("binary SHA");ByteBuffer b=ByteBuffer.allocateDirect(raw.length);b.put(raw).flip();int p=GL20.glCreateProgram();GL41.glProgramBinary(p,d.get("format").getAsInt(),b);if(GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)!=0)n++;GL20.glDeleteProgram(p);GL11.glGetError();}rows.add(Map.of("core",core,"forward",forward,"debug",debug,"noerror",noerror,"robust",robust,"created",true,"accepted",n,"actual_flags",GL11.glGetInteger(GL30.GL_CONTEXT_FLAGS)));System.out.println("R8 binary core="+core+" forward="+forward+" debug="+debug+" noerror="+noerror+" robust="+robust+" accepted="+n);GLFW.glfwDestroyWindow(w);}GLFW.glfwTerminate();Files.writeString(out.resolve("binary-probe.json"),new GsonBuilder().setPrettyPrinting().create().toJson(rows));}}
